<?php
namespace App\Application\Payments\Services;
use App\Domain\Contracts\Repositories\PaymentRepositoryInterface;use App\Domain\Contracts\TransactionManagerInterface;use App\Domain\Models\Order;use App\Domain\Models\PaymentTransaction;use Illuminate\Support\Str;use InvalidArgumentException;
class PaymentService{public function __construct(private readonly PaymentRepositoryInterface $repository,private readonly TransactionManagerInterface $transactions){}public function createCod(Order $order):PaymentTransaction{return $this->transactions->run(function()use($order){if($order->payment_status!=='pending')throw new InvalidArgumentException('حالة الدفع لا تسمح بإنشاء معاملة.');$p=$this->repository->createForOrder($order,['user_id'=>$order->user_id,'method'=>'cod','status'=>'pending','amount'=>$order->grand_total]);$order->update(['payment_method'=>'cod']);return $p;});}public function confirm(string $id,string $userId,string $status,?string $transactionId=null,array $payload=[]):PaymentTransaction{return $this->transactions->run(function()use($id,$userId,$status,$transactionId,$payload){$p=$this->repository->findForUser($id,$userId);if($p->status!=='pending')throw new InvalidArgumentException('المعاملة تمت معالجتها مسبقًا.');$p=$this->repository->confirm($p,['status'=>$status,'transaction_id'=>$transactionId?:($status==='successful'?'TX-'.Str::upper(Str::random(12)):null),'payload'=>$payload]);$p->order->update(['payment_status'=>$status==='successful'?'paid':'failed']);return $p;});}}
